from wcommon import dims_G, dims_M, legend, notes, head, sched
LAYER = "E-SPEAKER"
ROWS=[(lambda s,x,y: s.speaker(x,y,0.14,0), "سماعة سقفية/جدارية 6.5 بوصة 6W نظام 100V - تغطية 25 م²", "ceiling speaker 6.5\" 6W 100V"),
      (lambda s,x,y: s.box_label(x,y,"AMP",h=0.08,w=0.5,color=7), "مكبر صوت 120W 100V مع مشغل بلوتوث/USB", "amplifier 120W + BT/USB player")]
def _d(s,floor,pts,amp,t):
    for p in pts: s.speaker(*p,0.2,2.6)
    s.box_label(*amp,"AMP",h=0.1,w=0.6,color=7); s.text(amp[0],amp[1]-0.3,t,h=0.09,attach=2)
    (dims_G if floor=="G" else dims_M)(s,pts)
    legend(s,floor,"رموز السماعات - AUDIO LEGEND",ROWS)
    sched(s,floor,"جدول نظام الصوت",["البند","المواصفة","العدد"],[("سماعات","سقفية 6.5 بوصة 6W محول 100V لون أسود",f"{len(pts)}"),("مكبر","120W 100V مع بلوتوث + USB + مدخل ميكروفون","1"),("كابل","2×1.5 مم² كابل سماعات مجدول",f"{len(pts)*12} م"),("تحكم","منظم صوت جداري لكل منطقة","2")])
    notes(s,floor,["السماعات على السقف الأسود المكشوف بلون أسود، توزيع متجانس بمستوى 70 ديسيبل بالجلسات و 60 بالممرات.","المكبر بالكاشير (الأرضي) مع مشغل بلوتوث، ومنظم صوت مستقل للميزانين.","الأبعاد الحمراء: مواقع السماعات عن الجدران وبين بعضها."],"ملاحظات")
def draw_G(s): _d(s,"G",[(10.4,37.6),(13.4,37.6),(11.9,40.6),(11.9,43.0),(11.85,46.5),(11.85,52.5)],(11.25,39.8),"مكبر + مشغل بالكاشير"); head(s,"G","مخطط السماعات - الدور الأرضي: 4 سماعات بالصالة والمدخل، سماعة بالمطبخ وأخرى بالتحضير، المكبر بالكاشير.")
def draw_M(s): _d(s,"M",[(2.4,17.9),(6.4,17.9),(2.4,21.4),(6.4,21.4),(4.4,24.0),(6.2,26.2),(18.0,15.0),(12.5,23.3),(19.0,23.3)],(20.3,21.5),"منظم صوت + مكبر فرعي بالسيرفر"); head(s,"M","مخطط السماعات - الميزانين: 4 سماعات بالجلسات، الممر، مدخل الحمامات، الاجتماعات، المكاتب المفتوحة.")
